package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type InputReader struct {
	reader *bufio.Reader
}

func (ir *InputReader) readln() string {
	line, _ := ir.reader.ReadString('\n')
	return strings.TrimSpace(line)
}

func (ir *InputReader) readlnInt() int {
	return int(ir.readlnLong())
}

func (ir *InputReader) readlnLong() int64 {
	n, _ := strconv.ParseInt(ir.readln(), 10, 64)
	return n
}

func (ir *InputReader) readlnStrings() []string {
	return strings.Split(ir.readln(), " ")
}

func (ir *InputReader) readlnInts() []int {
	strs := ir.readlnStrings()
	vals := make([]int, len(strs))
	for i, s := range strs {
		vals[i] = int(ir.readlnLong())
	}
	return vals
}

func main() {
	ir := &InputReader{reader: bufio.NewReader(os.Stdin)}
	n, k := ir.readlnInt(), ir.readlnInt()
	a := ir.readlnInts()
	lim := a[k-1]
	ans := 0
	for _, v := range a {
		if v > 0 && v >= lim {
			ans++
		}
	}
	fmt.Print(ans)
}
